{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Currently, there is no clarity regarding the prevalence of SARS-CoV-2 infection among HCWs according to specific clinical settings, limiting the possibility of designing effective preventive measures to limit the transmission of the virus within a hospital, and from hospitals to the community (9, 10). Furthermore, it is unknown whether the clinical characteristics and outcomes of HCWs may be different from those of the general population, considering that the repeated exposure to the virus may lead to higher SARS-CoV2 viral load and, therefore, to worse clinical outcomes (11, 12).",
      "reason": "The introduction describes the current state of knowledge and highlights key uncertainties about prevalence by setting and differences in clinical characteristics/outcomes among HCWs."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Therefore, characterizing SARS-CoV-2 infection within HCWs is critical for achieving optimal control of the pandemic. With the present systematic review and meta-analysis, we aimed to identify, analyze, and quantify the prevalence, risk factors, clinical characteristics, and outcomes of COVID-19 among HCWs.",
      "reason": "The authors state the public health importance and justify the need for the review, and explicitly state the review's aims."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "To our knowledge, this is the first systematic review quantifying the burden of COVID-19 among HCWs.",
      "reason": "The manuscript explicitly addresses the existence of prior similar reviews by stating this is the first such systematic review, thereby explaining the need relative to prior work."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_1",
      "quote": "With the present systematic review and meta-analysis, we aimed to identify, analyze, and quantify the prevalence, risk factors, clinical characteristics, and outcomes of COVID-19 among HCWs.",
      "reason": "The review focuses on prevalence, risk factors, clinical characteristics, and outcomes rather than evaluating interventions; therefore a mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_1",
      "quote": "With the present systematic review and meta-analysis, we aimed to identify, analyze, and quantify the prevalence, risk factors, clinical characteristics, and outcomes of COVID-19 among HCWs.",
      "reason": "The review does not evaluate a complex intervention or delivery context, so a logic model is not applicable."
    }
  ],
  "confidence": "80"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "With the present systematic review and meta-analysis, we aimed to identify, analyze, and quantify the prevalence, risk factors, clinical characteristics, and outcomes of COVID-19 among HCWs.",
      "reason": "The manuscript explicitly states the review objectives in a question-formulation manner, specifying the aims to identify, analyze, and quantify prevalence, risk factors, clinical characteristics, and outcomes among health-care workers."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "All observational studies (eg, cross-sectional, cohort, case-control studies, and case series) except for case reports were included. We included studies that reported the prevalence of COVID-19 in HCWs, using either reverse transcription-polymerase chain reaction (RT-PCR) or a serum antibodies assay. We also included studies evaluating the risk factors for SARS-CoV-2 infection and those analyzing the clinical characteristics and outcomes of laboratory-confirmed COVID-19 among HCWs.",
      "reason": "This review synthesizes observational prevalence, risk factor, clinical characteristics, and outcome studies rather than intervention effects; therefore PICO-style planned comparisons for interventions are not applicable."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "All observational studies (eg, cross-sectional, cohort, case-control studies, and case series) except for case reports were included. We included studies that reported the prevalence of COVID-19 in HCWs, using either reverse transcription-polymerase chain reaction (RT-PCR) or a serum antibodies assay. We also included studies evaluating the risk factors for SARS-CoV-2 infection and those analyzing the clinical characteristics and outcomes of laboratory-confirmed COVID-19 among HCWs. We excluded those articles that evaluated HCWs with suspected but not laboratory-confirmed SARS-CoV-2 infection.",
      "reason": "Study designs and types of outcomes/tests used for eligibility are explicitly specified (observational designs, exclusion of case reports, requirement for laboratory-confirmation, types of analyses included). However, other study-characteristic eligibility details (e.g., eligible settings in general, follow-up requirements) are not explicitly specified in the provided evidence, so the element is only partially satisfied."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Medline, Embase, Latin American and Caribbean Health Sciences Literature (LILACS), Cochrane, Web of Science, the World Health Organization COVID-19 database, Google Scholar, and Living Evidence on COVID-19, a database developed by the Institute of Social and Preventive Medicine, University of Bern, were searched to identify relevant articles from inception until July 8, 2020, without language restrictions. ... We limited our search to human studies, with no language restriction.",
      "reason": "The search end date and that there were no language restrictions are explicitly reported. However, the provided evidence does not clearly state formal eligibility restrictions by dissemination year or publication/report status (although limitations note inclusion of preprints, there is no explicit eligibility criteria statement about publication/report status), so this element is only partially met."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence in the provided text distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "On the basis of the data from each study (extracted by 2 independent investigators), we first estimated the global prevalence of SARS-CoV-2 infection by each test used for screening (RT-PCR vs. antibodies tests). ... Screening criteria, geographic location, HCW professions, the clinical setting, and the mean of daily new cases of SARS-CoV-2 per million inhabitants (15) in the country during the period in which the study was carried out were prespecified as characteristics for assessment of heterogeneity and were evaluated using stratified analyses and univariate random-effects meta-regression.",
      "reason": "The manuscript specifies the groups used in syntheses (e.g., by test type: RT-PCR vs antibodies; and stratified analyses by screening criteria, location, profession, clinical setting, epidemic intensity), linking these groupings to planned comparisons/heterogeneity assessments."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not present rationales for notable restrictions on study eligibility (for example, no explanation for excluding non-laboratory-confirmed cases beyond stating the exclusion). No explicit justification for other eligibility restrictions is given in the retrieved text."
    }
  ],
  "confidence": "85"
}

